import sys

data = sys.stdin.read().split()
n, m, d = int(data[0]), int(data[1]), int(data[2])
a = [int(v) for v in data[3:3 + n]]
b = [int(v) for v in data[3 + n:3 + n + m]]
match = [-1] * m

def try_k(i, seen):
    for j in range(m):
        if a[i] <= b[j] <= a[i] + d and not seen[j]:
            seen[j] = True
            if match[j] == -1 or try_k(match[j], seen):
                match[j] = i
                return True
    return False

res = 0
for i in range(n):
    if try_k(i, [False] * m):
        res += 1
print(res)

